                await runAgentPrompt(env, {
                  sessionKey: config.sessionKey,
                  message: 'REPLAY-PHOTO-PROOF-TOOLS: check six files, then answer.',
                  timeoutMs: 600000,
                });
                while (!state.getSnapshot().messages.some((message) => message.direction === 'outbound' && String(message.text ?? '').includes('REPLAY-PHOTO-PROOF-DONE'))) {
                  if (Date.now() - started > 600000) break;
                  await sleep(50);
                }
                const ms = Date.now() - started;
                done = true;
                await watcher;
                return { ms, requestTimes, requests: await describeRequests(followUpStartCursor) };
