### Replay path benchmark

The script below drives the real admission path (`parseMessageWithAttachments` → `persistInboundImagesForTranscript` → `buildPersistedUserTurnMessage`, with a JSON round trip like the transcript) into a real agent-core `Agent` that has the same transform and media options as `attempt-setup.ts`. It then runs one follow-up turn with 8 tool rounds (9 model requests). Each scenario runs in its own process, and the warm-up uses a different image, so the first request of a scenario is a cold encode on both trees. Main and PR alternate, 2 runs each, and the two runs agree within a few percent:

| History image | main, follow-up turn | PR, follow-up turn | main, per request | PR, per request |
| --- | ---: | ---: | ---: | ---: |
| 12 MP phone JPEG (4032x3024) | 8.0 s | 0.17-0.18 s | 887-891 ms | 17-19 ms |
| three such photos | 24.1 s | 0.45 s | 2,675 ms | 49-50 ms |
| 3840x2160 photo | 5.7 s | 0.13 s | 634-635 ms | 15 ms |
| 2880x1800 PNG screenshot | 3.6 s | 0.03 s | 398-402 ms | 3 ms |
| 1179x2556 PNG screenshot | 2.5 s | 0.04 s | 274 ms | 4 ms |
| 1600x900 JPEG, kept as is (control) | 85 ms | 84 ms | 9 ms | 9 ms |
| no image (control) | 2 ms | 2 ms | 0 ms | 0 ms |

The image sha256 matched between trees in every row. Max RSS of the benchmark process was 1.0 to 1.1 GB on both trees, with no consistent difference.

<details>
<summary>Benchmark script</summary>

```ts
// Times a follow-up turn after a stored photo, through the real replay path.
// Run once per checkout from that checkout's directory:
//   REPO=$PWD FIXTURES=<dir with images> OPENCLAW_STATE_DIR=<scratch>/state HOME=<scratch>/home \
//     SCEN="phone-4032x3024.jpg" WARM=retina-2880x1800.png ROUNDS=0,4,8 TURNS=5 \
//     node_modules/.bin/tsx bench-replay-photo.mts
// End to end: real chat.send attachment admission (parseMessageWithAttachments ->
// persistInboundImagesForTranscript -> buildPersistedUserTurnMessage, JSON round trip like the
// transcript), then a real agent-core Agent running a follow-up turn with K tool rounds, with the
// exact transform attempt-setup installs (installHistoryImagePruneContextTransform + mediaOptions).
// Measures wall clock of the whole follow-up turn and of each per-request transform.
import { createHash } from "node:crypto";
import fs from "node:fs";
import { monitorEventLoopDelay } from "node:perf_hooks";

const R = process.env.REPO ?? "";
if (!R) throw new Error("set REPO");
const FIXTURES = process.env.FIXTURES ?? "";
if (!FIXTURES || !process.env.OPENCLAW_STATE_DIR) {
  throw new Error("set FIXTURES and a scratch OPENCLAW_STATE_DIR");
}

const { parseMessageWithAttachments, persistInboundImagesForTranscript } = await import(
  `${R}/src/gateway/chat-attachments.ts`
);
const { buildPersistedUserTurnMessage } = await import(`${R}/src/sessions/user-turn-transcript.ts`);
const { installHistoryImagePruneContextTransform } = await import(
  `${R}/src/agents/embedded-agent-runner/run/history-image-prune.ts`
);
const { Agent } = await import(`${R}/packages/agent-core/src/agent.ts`);
const { makeTool, makeCall, reply, TEST_USAGE } = await import(
  `${R}/packages/agent-core/src/agent-loop.test-support.ts`
);
const { MAX_IMAGE_BYTES } = await import(`${R}/packages/media-core/src/constants.ts`);
const { resolveImageSanitizationLimits } = await import(`${R}/src/agents/image-sanitization.ts`);
const { getAgentScopedMediaLocalRoots } = await import(`${R}/src/media/local-roots.ts`);
const { resolveChatAttachmentMaxBytes } = await import(`${R}/src/gateway/chat-attachment-policy.ts`);

const model = {
  id: "claude-sonnet-4-5",
  name: "vision",
  api: "anthropic-messages",
  provider: "anthropic",
  baseUrl: "https://example.invalid",
  reasoning: false,
  input: ["text", "image"],
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
  contextWindow: 200_000,
  maxTokens: 8000,
};
const cfg = {};
const log = { warn: (m: string) => console.error("WARN", m), info: () => {} };

const mimeOf = (f: string) => (f.endsWith(".png") ? "image/png" : "image/jpeg");

// chat.send admission of one photo, persisted exactly like prepareChatSendUserTurn does.
async function admitPhotoTurn(text: string, file: string, timestamp: number) {
  const buf = fs.readFileSync(`${FIXTURES}/${file}`);
  const parsed = await parseMessageWithAttachments(
    text,
    [{ type: "image", mimeType: mimeOf(file), fileName: file, content: buf.toString("base64") }],
    { maxBytes: resolveChatAttachmentMaxBytes(cfg), log, supportsImages: true, acceptNonImage: true },
  );
  const persisted = await persistInboundImagesForTranscript({
    images: parsed.images,
    offloadedRefs: parsed.offloadedRefs,
    log,
    logContext: "chat.send",
  });
  const media = persisted.entries.map((entry: any) => entry.fact);
  const slots = persisted.entries.flatMap((entry: any, factIndex: number) =>
    entry.imageKind ? [{ kind: entry.imageKind, factIndex }] : [],
  );
  const msg = buildPersistedUserTurnMessage({
    text: parsed.message,
    timestamp,
    ...(media.length ? { media } : {}),
    ...(slots.length ? { mediaImageLayout: { slots } } : {}),
  });
  // Transcript JSONL round trip.
  return { msg: JSON.parse(JSON.stringify(msg)), kinds: slots.map((s: any) => s.kind) };
}

function assistant(content: any[], ts: number) {
  return {
    role: "assistant",
    content,
    api: model.api,
    provider: model.provider,
    model: model.id,
    usage: TEST_USAGE,
    stopReason: content.some((c) => c.type === "toolCall") ? "toolUse" : "stop",
    timestamp: ts,
  };
}

async function buildHistory(completedTurns: number, photos: string[]) {
  const msgs: any[] = [];
  let ts = 1_700_000_000_000;
  const photoStart = completedTurns - photos.length; // photos in the most recent completed turns
  const kinds: string[] = [];
  for (let t = 0; t < completedTurns; t++) {
    const photo = t >= photoStart ? photos[t - photoStart] : undefined;
    if (photo) {
      const { msg, kinds: k } = await admitPhotoTurn(`look at this ${t}`, photo, ts++);
      msgs.push(msg);
      kinds.push(...k);
    } else {
      msgs.push(buildPersistedUserTurnMessage({ text: `question ${t} ` + "x".repeat(200), timestamp: ts++ }));
    }
    const id = `call_${t}`;
    msgs.push(assistant([{ type: "toolCall", id, name: "read", arguments: {} }], ts++));
    msgs.push({
      role: "toolResult",
      toolCallId: id,
      toolName: "read",
      content: [{ type: "text", text: "file contents ".repeat(150) }],
      isError: false,
      timestamp: ts++,
    });
    msgs.push(assistant([{ type: "text", text: `answer ${t} ` + "y".repeat(400) }], ts++));
  }
  return { msgs, kinds };
}

function mediaOptions() {
  // Mirrors attempt-setup.ts:317-334 for a default, non-sandboxed, non-workspaceOnly agent.
  return {
    workspaceDir: `${process.env.OPENCLAW_STATE_DIR}/workspace`,
    agentWorkspaceDir: `${process.env.OPENCLAW_STATE_DIR}/workspace`,
    model,
    maxBytes: MAX_IMAGE_BYTES,
    maxDimensionPx: resolveImageSanitizationLimits(cfg).maxDimensionPx,
    workspaceOnly: false,
    localRoots: getAgentScopedMediaLocalRoots(cfg, "main"),
    sandbox: undefined,
  };
}

function imageInfo(messages: any[]) {
  const out: string[] = [];
  for (const m of messages) {
    if (!Array.isArray(m.content)) continue;
    for (const b of m.content) {
      if (b.type !== "image") continue;
      const bytes = Buffer.from(b.data, "base64");
      out.push(`${b.mimeType}:${bytes.length}:${createHash("sha256").update(bytes).digest("hex").slice(0, 8)}`);
    }
  }
  return out;
}

async function runFollowUpTurn(opts: { completedTurns: number; photos: string[]; toolRounds: number }) {
  const { msgs, kinds } = await buildHistory(opts.completedTurns, opts.photos);
  const transformMs: number[] = [];
  const requestImages: string[][] = [];
  let turn = 0;
  const agent = new Agent({
    initialState: { model, messages: msgs, tools: [makeTool("read")] },
    streamFn: (_m: any, context: any) => {
      requestImages.push(imageInfo(context.messages));
      turn += 1;
      return reply(
        assistant(
          turn <= opts.toolRounds
            ? [makeCall("read", `cur_${turn}`)]
            : [{ type: "text", text: "done" }],
          Date.now(),
        ) as any,
      );
    },
  });
  installHistoryImagePruneContextTransform(agent, mediaOptions(), () => {});
  const inner = agent.transformContext!;
  agent.transformContext = async (m: any, s?: AbortSignal) => {
    const t0 = performance.now();
    const r = await inner(m, s);
    transformMs.push(performance.now() - t0);
    return r;
  };
  const h = monitorEventLoopDelay({ resolution: 5 });
  h.enable();
  const t0 = performance.now();
  await agent.prompt("follow-up question");
  const total = performance.now() - t0;
  h.disable();
  return { total, transformMs, requestImages, kinds, elMaxMs: h.max / 1e6 };
}

const fmt = (xs: number[]) => xs.map((x) => x.toFixed(0)).join(",");
const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]!;

// Warm the worker pool / WASM once so it is not attributed to any scenario.
await runFollowUpTurn({ completedTurns: 4, photos: [process.env.WARM ?? "phone-4032x3024.jpg"], toolRounds: 0 });

if (process.env.CONCURRENT) {
  // N independent sessions running a follow-up turn at the same time (shared 2-worker image pool).
  for (const n of process.env.CONCURRENT.split(",").map(Number)) {
    const t0 = performance.now();
    const results = await Promise.all(
      Array.from({ length: n }, () =>
        runFollowUpTurn({ completedTurns: 5, photos: ["phone-4032x3024.jpg"], toolRounds: 2 }),
      ),
    );
    console.log(
      `concurrentSessions=${n} wall=${(performance.now() - t0).toFixed(0)}ms perRequestTransform medians=[${results
        .map((r) => median(r.transformMs).toFixed(0))
        .join(",")}]ms`,
    );
  }
  process.exit(0);
}

const scenarios: Array<{ label: string; photos: string[] }> = (
  process.env.SCEN ??
  "none;small-1600x900.jpg;phone-4032x3024.jpg;phone-4032x3024.jpg,phone-4032x3024.jpg,phone-4032x3024.jpg;real-3840x2160.jpg;retina-2880x1800.png;iphone-1179x2556.png"
)
  .split(";")
  .map((s) => ({ label: s, photos: s === "none" ? [] : s.split(",") }));
const rounds = (process.env.ROUNDS ?? "0,4,8").split(",").map(Number);
const turnsList = (process.env.TURNS ?? "5,60").split(",").map(Number);

for (const completedTurns of turnsList) {
  for (const sc of scenarios) {
    for (const toolRounds of rounds) {
      const r = await runFollowUpTurn({ completedTurns, photos: sc.photos, toolRounds });
      const first = r.requestImages[0] ?? [];
      const stable = r.requestImages.every((x) => JSON.stringify(x) === JSON.stringify(first));
      console.log(
        `turns=${completedTurns} msgs=${completedTurns * 4 + 1} photos=[${sc.label}] slots=${r.kinds.join("/") || "-"} rounds=${toolRounds} requests=${r.transformMs.length} ` +
          `turnTotal=${r.total.toFixed(0)}ms perRequestTransform median=${median(r.transformMs).toFixed(1)}ms [${fmt(r.transformMs)}] ` +
          `imagesSent=${first.length} ${first.join(" ")} stableBytes=${stable} eventLoopMax=${r.elMaxMs.toFixed(0)}ms`,
      );
    }
  }
}
process.exit(0);
```

