  stderr = `${stderr}${chunk.toString("utf8")}`.slice(-4_000);
});

const watchdog = setTimeout(() => child.kill("SIGKILL"), 30_000);
const exitCode = await new Promise<number | null>((resolve, reject) => {
  child.once("error", reject);
  child.once("close", resolve);
});
clearTimeout(watchdog);

const complete = stdout.match(/OTEL_SHUTDOWN_COMPLETE:(\{[^\n]+\})/u)?.[1];
const shutdown = complete ? JSON.parse(complete) as {
  stopDurationMs: number;
  metricFailureReported: boolean;
} : null;
const result = {
  headSha,
  boundary: "real diagnostics-otel service and OTLP metric exporter against refused loopback collector",
  endpoint: "http://127.0.0.1:9",
  healthyMetricRequestCount,
  startupDurationMs: readyAt === undefined ? null : readyAt - startedAt,
  stopDurationMs: shutdown?.stopDurationMs ?? null,
  exitAfterStopMs: stopCompletedAt === undefined ? null : performance.now() - stopCompletedAt,
  metricFailureReported: shutdown?.metricFailureReported ?? false,
  childExitCode: exitCode,
  stdout,
  stderr,
};
console.log(JSON.stringify(result));

if (
  exitCode !== 0
  || readyAt === undefined
  || !shutdown
  || !shutdown.metricFailureReported
  || stopCompletedAt === undefined
) {
  process.exitCode = 1;
}
```
